Lemma sec_eager_room : forall Σ n, rt_wf Σ -> 64512 < n -> mcost n <= credit Σ ->
  smsz n <= mcost n /\ rt_eager Σ + smsz n + 8 * (0x4000 - sec_nres Σ) <= 2 ^ 38.
